(()=>{'use strict';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const money=n=>'₹'+n.toLocaleString('en-IN');
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const summaries=[
['A focused workspace for legal matters.','A law firm CRM brings matters, client records, hearing dates, and follow-ups into one view. Explore a sample matter register: search a case, inspect its details, or create a new matter.','MATTER REGISTER / CLIENT RECORDS / FOLLOW-UPS'],
['From first enquiry to a clear next step.','A CRM workspace for tracking enquiries and moving opportunities through a sales pipeline. Select an opportunity, move it to the next stage, and watch the pipeline totals update.','LEAD PIPELINE / OPPORTUNITIES / ACTIVITY'],
['Scan. Choose. Order.','A table-side food ordering experience built around a simple menu and an easy-to-review cart. Choose dishes, adjust quantities, and place a sample order to follow its status.','QR MENU / CART / ORDER TRACKING'],
['A connected view of site operations.','An ERP workspace for construction procurement, approval queues, and project spending. Review sample purchase requests and try a rule-based budget check before making an approval decision.','PROCUREMENT / APPROVALS / BUDGET REVIEW'],
['Every room. Every payment. In view.','A PG management workspace for occupancy, resident records, and monthly rent. Filter the resident register, record a sample payment, and see outstanding dues change immediately.','RESIDENTS / OCCUPANCY / RENT REGISTER'],
['A better everyday experience for residents.','An apartment management workspace that connects resident requests with maintenance follow-through. Create a sample request, filter by status, and resolve an issue from the same view.','RESIDENT REQUESTS / MAINTENANCE / STATUS TRACKING']
];
const icons=['⚖','↗','M','J','V','K'];
const cards=$$('#projects .project-card');
function shell(i,title,nav,body){return `<div class="project-app theme-${i}" data-preview="${i}"><div class="pa-top"><span class="pa-logo">${icons[i]}</span><strong>${title}</strong><span class="pa-sample">SAMPLE WORKSPACE</span></div><div class="pa-layout"><aside class="pa-sidebar"><span class="pa-nav-active">${nav}</span><span>WORKSPACE</span><span>Sample records</span><span class="pa-avatar">OS <small>OneSash preview</small></span></aside><div class="pa-main">${body}</div></div><div class="pa-toast" role="status" aria-live="polite">Explore this interface. Changes stay in this preview.</div></div>`}
const head=(label,title,action='')=>`<div class="pa-heading"><div><small>${label}</small><h4>${title}</h4></div>${action}</div>`;
const stat=(label,value)=>`<div><span>${label}</span><strong>${value}</strong></div>`;
const button=(label,action,extra='')=>`<button type="button" data-action="${action}" ${extra}>${label}</button>`;
const state={cases:[{id:'MAT-024',name:'Property documentation',client:'Client A',date:'18 Nov',type:'Property',status:'In progress'},{id:'MAT-025',name:'Commercial agreement',client:'Client B',date:'21 Nov',type:'Corporate',status:'Review'},{id:'MAT-026',name:'Civil petition',client:'Client C',date:'25 Nov',type:'Civil',status:'In progress'}],leads:[{name:'North office connectivity',value:42000,stage:0},{name:'Campus network upgrade',value:125000,stage:1},{name:'Managed support plan',value:68000,stage:2}],cart:{},order:null,requests:[{name:'Structural steel',vendor:'Sample vendor A',cost:185000,status:'Pending'},{name:'Electrical fixtures',vendor:'Sample vendor B',cost:48000,status:'Pending'},{name:'Safety equipment',vendor:'Sample vendor C',cost:16000,status:'Pending'}],residents:[{name:'Resident A',room:'101 · Bed A',rent:7500,paid:false},{name:'Resident B',room:'101 · Bed B',rent:7500,paid:true},{name:'Resident C',room:'102 · Bed A',rent:8500,paid:false},{name:'Resident D',room:'103 · Bed A',rent:8000,paid:true}],tickets:[{name:'Water pressure is low',unit:'A-204',category:'Plumbing',status:'Open'},{name:'Lobby light replacement',unit:'Common area',category:'Electrical',status:'In progress'},{name:'Lift inspection request',unit:'Block B',category:'Facilities',status:'Resolved'}]};
const menu=[{name:'Pesto pasta',desc:'Basil pesto · parmesan · penne',price:240,category:'Mains',art:'pasta'},{name:'Garden pizza',desc:'Roasted vegetables · mozzarella',price:320,category:'Mains',art:'pizza'},{name:'Cold coffee',desc:'Chilled espresso · milk',price:140,category:'Drinks',art:'coffee'}];
const apps=[];
function say(i,text){$('.pa-toast',apps[i]).textContent=text}
function renderLaw(filter=''){const app=apps[0],rows=state.cases.filter(c=>(c.name+' '+c.client+' '+c.type).toLowerCase().includes(filter.toLowerCase()));$('.law-count',app).textContent=state.cases.length;$('.law-rows',app).innerHTML=rows.map(c=>`<button type="button" class="pa-record" data-case="${c.id}"><span><small>${c.id} / ${escape(c.type)}</small><b>${escape(c.name)}</b><em>${escape(c.client)}</em></span><span><i class="pa-badge">${c.status}</i><small>${c.date} ↗</small></span></button>`).join('')||'<p class="pa-empty">No matching matters. Try a different search.</p>'}
function renderCRM(){const app=apps[1],stages=['New','Qualified','Proposal','Won'];$('.crm-total',app).textContent=money(state.leads.filter(l=>l.stage<3).reduce((n,l)=>n+l.value,0));$('.crm-board',app).innerHTML=stages.map((stage,j)=>`<div class="pa-column"><h5>${stage}<span>${state.leads.filter(l=>l.stage===j).length}</span></h5>${state.leads.map((l,k)=>l.stage===j?`<div class="pa-opportunity"><small>OPP / 0${k+1}</small><b>${l.name}</b><strong>${money(l.value)}</strong>${j<3?button('Move to '+stages[j+1]+' →','advance',`data-lead="${k}"`):'<span class="pa-badge">Won ✓</span>'}</div>`:'').join('')}</div>`).join('')}
function renderMenu(category='All'){const app=apps[2];$('.food-menu',app).innerHTML=menu.map((m,k)=>category==='All'||m.category===category?`<div class="food-item"><div class="food-art ${m.art}" aria-hidden="true"><i></i><b></b></div><div><h5>${m.name}</h5><small>${m.desc}</small><strong>${money(m.price)}</strong></div>${button('＋','add-food',`data-food="${k}" aria-label="Add ${m.name}"`)}</div>`:'').join('')}
function renderCart(){const app=apps[2],entries=Object.entries(state.cart).filter(([,q])=>q>0),total=entries.reduce((n,[k,q])=>n+menu[k].price*q,0);$('.food-cart',app).innerHTML=entries.length?entries.map(([k,q])=>`<div class="cart-row"><span>${menu[k].name}</span><div>${button('−','remove-food',`data-food="${k}" aria-label="Remove one ${menu[k].name}"`)}<b>${q}</b>${button('+','add-food',`data-food="${k}" aria-label="Add one ${menu[k].name}"`)}</div><strong>${money(q*menu[k].price)}</strong></div>`).join(''):'<p class="pa-empty">Your table is ready.<br>Add something delicious.</p>';$('.food-total',app).textContent=money(total);$('[data-action="order"]',app).disabled=!entries.length}
function renderERP(){const app=apps[3];$('.erp-pending',app).textContent=state.requests.filter(r=>r.status==='Pending').length;$('.erp-committed',app).textContent=money(state.requests.filter(r=>r.status==='Approved').reduce((n,r)=>n+r.cost,0));$('.erp-rows',app).innerHTML=state.requests.map((r,k)=>`<div class="pa-record"><span><small>PR / 0${k+1} · ${r.vendor}</small><b>${r.name}</b><em>${money(r.cost)}</em></span><span>${r.status==='Pending'?button('Review →','review',`data-request="${k}"`):`<i class="pa-badge">${r.status}</i>`}</span></div>`).join('')}
function renderPG(filter='all'){const app=apps[4],dues=state.residents.filter(r=>!r.paid).reduce((n,r)=>n+r.rent,0);$('.pg-dues',app).textContent=money(dues);$('.pg-rows',app).innerHTML=state.residents.map((r,k)=>filter==='due'&&r.paid?'':`<div class="pa-record"><span><small>ROOM ${r.room}</small><b>${r.name}</b><em>Monthly rent ${money(r.rent)}</em></span><span>${r.paid?'<i class="pa-badge">Paid ✓</i>':button('Record payment','pay',`data-resident="${k}"`)}</span></div>`).join('')||'<p class="pa-empty">All rent payments are up to date.</p>'}
function renderTickets(filter='all'){const app=apps[5];$('.ticket-open',app).textContent=state.tickets.filter(t=>t.status!=='Resolved').length;$('.ticket-rows',app).innerHTML=state.tickets.map((t,k)=>filter!=='all'&&t.status!==filter?'':`<div class="pa-record"><span><small>${escape(t.unit)} / ${escape(t.category)}</small><b>${escape(t.name)}</b><em>${t.status}</em></span>${t.status==='Resolved'?'<span class="pa-badge">Resolved ✓</span>':button('Resolve ✓','resolve',`data-ticket="${k}"`)}</div>`).join('')||'<p class="pa-empty">No requests in this view.</p>'}
const bodies=[
head('LAWTHRONE-NRJM / LEGAL OPERATIONS','Matter register',button('+ New matter','new-matter'))+`<div class="pa-stats">${stat('Active matters','<span class="law-count">3</span>')}${stat('Next hearing','18 Nov')}</div><label class="pa-search">⌕ <input type="search" placeholder="Search matters or clients" aria-label="Search matters or clients"></label><div class="law-rows"></div><div class="pa-detail" hidden></div>`,
head('ALS-INFONET / SALES WORKSPACE','Opportunity pipeline',button('Reset pipeline','reset-crm'))+`<div class="pa-stats">${stat('Open pipeline','<span class="crm-total"></span>')}${stat('Opportunities','3')}</div><div class="crm-board"></div>`,
head('MAYOBISTRO / TABLE 07','Good food. No waiting.')+`<div class="food-tabs" aria-label="Menu category">${['All','Mains','Drinks'].map(c=>button(c,'food-category',`data-category="${c}" aria-pressed="${c==='All'}"`)).join('')}</div><div class="food-menu"></div><div class="food-basket"><h5>Your table order</h5><div class="food-cart"></div><div class="food-checkout"><span>Total <strong class="food-total">₹0</strong></span>${button('Place sample order →','order')}</div><div class="food-order" hidden></div></div>`,
head('JYOTHI BUILDERS / SITE OPERATIONS','Procurement desk')+`<div class="pa-stats">${stat('Awaiting review','<span class="erp-pending">3</span>')}${stat('Approved value','<span class="erp-committed">₹0</span>')}</div><div class="erp-budget"><span>Purchase review threshold</span><b>₹1,00,000</b><small>Preview uses a transparent budget rule. No live AI service is connected.</small></div><div class="erp-rows"></div><div class="pa-detail" hidden></div>`,
head('VENKATESWARA / RESIDENT WORKSPACE','November rent register')+`<div class="pa-stats">${stat('Occupied beds','4 / 6')}${stat('Outstanding','<span class="pg-dues"></span>')}</div><div class="pg-occupancy" aria-label="Four of six beds occupied"><i></i><i></i><i></i><i></i><i></i><i></i></div><label class="pa-filter">View <select aria-label="Filter residents"><option value="all">All residents</option><option value="due">Payment due</option></select></label><div class="pg-rows"></div>`,
head('KRISHNA APARTMENTS / COMMUNITY DESK','Resident requests',button('+ New request','new-ticket'))+`<div class="pa-stats">${stat('Unresolved','<span class="ticket-open">2</span>')}${stat('Community','Blocks A + B')}</div><label class="pa-filter">Status <select aria-label="Filter maintenance requests"><option value="all">All requests</option><option>Open</option><option>In progress</option><option>Resolved</option></select></label><div class="ticket-rows"></div>`
];
cards.forEach((card,i)=>{const copy=card.lastElementChild;$('.project-monogram',card)?.remove();const summary=summaries[i];$('p',copy).textContent=summary[1];const h=document.createElement('p');h.className='project-outcome';h.textContent=summary[0];$('h3',copy).after(h);const tags=document.createElement('p');tags.className='project-scope';tags.textContent=summary[2];copy.append(tags);const host=document.createElement('div');host.className='project-preview-host';host.innerHTML=shell(i,window.ONESASH_CONFIG.projects[i].title,['Matters','Pipeline','Menu','Purchases','Residents','Requests'][i],bodies[i]);card.prepend(host);apps[i]=$('.project-app',host);const tools=document.createElement('div');tools.className='project-preview-tools';tools.innerHTML=`<span>INTERACTIVE PREVIEW · SAMPLE DATA</span>${button('Expand workspace ↗','expand',`data-project="${i}"`)}${button('Reset','reset',`data-project="${i}"`)}`;host.append(tools);});
const initial=JSON.stringify(state);function renderAll(){renderLaw();renderCRM();renderMenu();renderCart();renderERP();renderPG();renderTickets()}renderAll();if(typeof ScrollTrigger!=='undefined')ScrollTrigger.refresh();
// Native dialog supplies focus containment and Escape behavior.
const modal=document.createElement('dialog');modal.className='project-modal';modal.setAttribute('aria-label','Interactive project workspace');modal.innerHTML='<div class="project-modal-top"><span>ONESASH / INTERACTIVE PROJECT PREVIEW</span><button type="button" data-close>Close ✕</button></div><div class="project-modal-body"></div>';document.body.append(modal);let expanded=null,returnButton=null;
function close(){if(expanded!==null){$('.project-preview-host',cards[expanded]).prepend(apps[expanded]);expanded=null}modal.close();document.body.style.overflow='';returnButton?.focus()}
$('[data-close]',modal).addEventListener('click',close);modal.addEventListener('cancel',e=>{e.preventDefault();close()});modal.addEventListener('click',e=>{if(e.target===modal)close()});
function form(i,title,fields,action){const detail=$('.pa-detail',apps[i])||document.createElement('div');if(!detail.parentNode){detail.className='pa-detail';$('.pa-main',apps[i]).append(detail)}detail.hidden=false;detail.innerHTML=`<form data-form="${action}"><div class="pa-heading"><h5>${title}</h5>${button('Cancel','cancel')}</div>${fields}<button type="submit">Save ${action==='matter'?'matter':'request'} →</button></form>`;$('input',detail)?.focus()}
const input=(label,name,placeholder)=>`<label>${label}<input required maxlength="80" name="${name}" placeholder="${placeholder}"></label>`;
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(action==='expand'){expanded=Number(b.dataset.project);returnButton=b;$('.project-modal-body',modal).append(apps[expanded]);modal.showModal();document.body.style.overflow='hidden';return}const app=b.closest('.project-app'),i=app?Number(app.dataset.preview):Number(b.dataset.project);if(action==='reset'){if(i===2)$$('.food-tabs button',apps[2]).forEach((t,j)=>t.setAttribute('aria-pressed',String(j===0)));const fresh=JSON.parse(initial);const keys=[['cases'],['leads'],['cart','order'],['requests'],['residents'],['tickets']][i];keys.forEach(k=>state[k]=fresh[k]);const renderers=[renderLaw,renderCRM,()=>{renderMenu();renderCart();$('.food-order',apps[2]).hidden=true},renderERP,renderPG,renderTickets];renderers[i]();$$('select',apps[i]).forEach(s=>s.selectedIndex=0);$$('.pa-detail',apps[i]).forEach(d=>d.hidden=true);$$('input[type=search]',apps[i]).forEach(s=>s.value='');say(i,'Workspace reset to sample data.');return}
if(action==='new-matter')form(i,'Create a matter',input('Matter title','name','e.g. Contract review')+input('Client reference','client','e.g. Client D')+input('Practice area','type','e.g. Corporate'),'matter');
if(action==='cancel')b.closest('.pa-detail').hidden=true;
if(action==='advance'){const l=state.leads[b.dataset.lead];if(l.stage<3)l.stage++;renderCRM();say(i,l.name+' moved to '+['New','Qualified','Proposal','Won'][l.stage]+'.')}
if(action==='reset-crm'){state.leads=JSON.parse(initial).leads;renderCRM();say(i,'Pipeline reset.')}
if(action==='food-category'){$$('.food-tabs button',app).forEach(t=>t.setAttribute('aria-pressed',String(t===b)));renderMenu(b.dataset.category)}
if(action==='add-food'||action==='remove-food'){const k=b.dataset.food;state.cart[k]=Math.max(0,(state.cart[k]||0)+(action==='add-food'?1:-1));renderCart();say(i,menu[k].name+' quantity: '+state.cart[k])}
if(action==='order'){const total=Object.entries(state.cart).reduce((n,[k,q])=>n+menu[k].price*q,0);if(!total)return;state.order={total,step:0};state.cart={};renderCart();const o=$('.food-order',app);o.hidden=false;o.innerHTML=`<small>SAMPLE ORDER / MB-007</small><h5>Order received ✓</h5><p>Table 07 · ${money(total)}</p><div class="order-steps"><b>Received</b><span>Preparing</span><span>Ready</span></div>${button('Update order status →','order-next')}`;say(i,'Sample order placed. No payment or kitchen request was sent.')}
if(action==='order-next'){const o=state.order;if(!o)return;o.step=Math.min(2,o.step+1);$('.food-order h5',app).textContent=['Order received ✓','Your food is being prepared','Ready for your table ✓'][o.step];$$('.order-steps>*',app).forEach((n,j)=>n.classList.toggle('done',j<=o.step));if(o.step===2)b.disabled=true;say(i,'Order status: '+['Received','Preparing','Ready'][o.step])}
if(action==='review'){const k=Number(b.dataset.request),r=state.requests[k],over=r.cost>100000,d=$('.pa-detail',app);d.hidden=false;d.innerHTML=`<h5>${r.name} / review</h5><p>${over?'Above the ₹1,00,000 threshold. Additional approval recommended.':'Within the review threshold. Standard approval route.'}</p><small>Rule-based sample assessment · ${money(r.cost)}</small><div class="pa-review-actions">${button('Approve request','approve',`data-request="${k}"`)}${button('Hold for review','hold',`data-request="${k}"`)}</div>`;say(i,'Budget check complete. Review the recommendation before deciding.')}
if(action==='approve'||action==='hold'){const r=state.requests[b.dataset.request];r.status=action==='approve'?'Approved':'On hold';renderERP();$('.pa-detail',app).hidden=true;say(i,r.name+': '+r.status+'.')}
if(action==='pay'){const r=state.residents[b.dataset.resident];r.paid=true;renderPG($('select',app).value);say(i,'Sample payment of '+money(r.rent)+' recorded for '+r.name+'. No money was collected.')}
if(action==='new-ticket')form(i,'New maintenance request',input('Issue','name','e.g. Corridor light flickering')+input('Apartment / location','unit','e.g. A-105')+input('Category','category','e.g. Electrical'),'ticket');
if(action==='resolve'){const t=state.tickets[b.dataset.ticket];t.status='Resolved';renderTickets($('select',app).value);say(i,t.name+' marked resolved.')}
});
apps[0].addEventListener('input',e=>{if(e.target.type==='search')renderLaw(e.target.value)});apps[4].addEventListener('change',e=>{if(e.target.tagName==='SELECT')renderPG(e.target.value)});apps[5].addEventListener('change',e=>{if(e.target.tagName==='SELECT')renderTickets(e.target.value)});
apps[0].addEventListener('click',e=>{const b=e.target.closest('[data-case]');if(!b)return;const c=state.cases.find(c=>c.id===b.dataset.case),d=$('.pa-detail',apps[0]);d.hidden=false;d.innerHTML=`<h5>${escape(c.name)}</h5><p>${escape(c.client)} · ${escape(c.type)}</p><p>Next action: ${c.date==='To schedule'?'Schedule first review':'Prepare documents for '+c.date}</p><span class="pa-badge">${c.status}</span>${button('Close details','cancel')}`;say(0,c.id+' opened.')});
document.addEventListener('submit',e=>{const f=e.target.closest('[data-form]');if(!f)return;e.preventDefault();if(!f.reportValidity())return;const values=Object.fromEntries(new FormData(f));if(Object.values(values).some(v=>!v.trim())){say(f.dataset.form==='matter'?0:5,'Enter a value in every field.');return}if(f.dataset.form==='matter'){state.cases.push({id:'MAT-'+(24+state.cases.length).toString().padStart(3,'0'),...values,date:'To schedule',status:'New'});$('input[type=search]',apps[0]).value='';renderLaw();say(0,'Matter created in this sample workspace.')}else{state.tickets.unshift({...values,status:'Open'});$('select',apps[5]).value='all';renderTickets();say(5,'Request created in this sample workspace.')}f.closest('.pa-detail').hidden=true});
})();
